def count_vowels(s: str) -> int:
    # Return number of vowels
    return sum(1 for c in s.lower() if c in 'aeiou')

def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        diff = target - num
        if diff in seen:
            return [seen[diff], i]
        seen[num] = i
    return []

