import numpy as np
def get_median(arr):
    return float(np.median(arr))

def is_unique_chars(s: str) -> bool:
    checker = 0
    for char in s:
        val = ord(char) - ord('a')
        if (checker & (1 << val)) > 0:
            return False
        checker |= (1 << val)
    return True
